const items = $input.all();

// Sort by timestamp descending, ambil 20 terakhir
const sorted = items
  .filter(i => i.json.role && i.json.message)
  .sort((a, b) => new Date(b.json.timestamp) - new Date(a.json.timestamp))
  .slice(0, 10)
  .reverse();

return sorted.length > 0 ? sorted : [{ json: {} }];

