const aiReply = $('Extract AI Reply').item.json.aiReply;

const tagMatch = aiReply.match(/REVENUE[:\s]*(\d[\d.,]*)/i);
if (tagMatch) {
  return [{ json: { revenue: parseInt(tagMatch[1].replace(/[.,]/g, '')) } }];
}

const parts = aiReply.split('|');
let revenue = 0;
for (const part of parts) {
  if (/ongkir|kirim|shipping|total/i.test(part)) continue;
  const priceMatch = part.match(/Rp\.?\s*([\d.,]+)/i);
  if (priceMatch) {
    const price = parseInt(priceMatch[1].replace(/[.,]/g, ''));
    if (price > 0) revenue += price;
  }
}

return [{ json: { revenue } }];

